    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0RC_1LC0RD_1LA1LB_1RB0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S0 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0RC_1LC0RD_1LA1LB_1RB0LC : list Instr := [].
Definition tmw_0RB0RC_1LC0RD_1LA1LB_1RB0LC : TM := tm_wrap_trs tmm_0RB0RC_1LC0RD_1LA1LB_1RB0LC pins_0RB0RC_1LC0RD_1LA1LB_1RB0LC.
