(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0RC_1LC0RD_1LA1LB_1RB0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_0RB0RC_1LC0RD_1LA1LB_1RB0LC.
