Lemma lbl_0RB0RC_1LC0RD_1LA1LB_1RB0LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0RC_1LC0RD_1LA1LB_1RB0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0RC_1LC0RD_1LA1LB_1RB0LC) = lift (Cc (Pos.succ p)).
