  apply (fire_of_run_instr tm Cc true true l B0_0RB0RC_1LC0RD_1LA1LB_1RB0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0RC_1LC0RD_1LA1LB_1RB0LC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0RC_1LC0RD_1LA1LB_1RB0LC : forall t, ~ In t pins_0RB0RC_1LC0RD_1LA1LB_1RB0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0RC_1LC0RD_1LA1LB_1RB0LC.
