Lemma geo_0RB0RD_0LC1RA_1RB1LC_0LB1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0RD_0LC1RA_1RB1LC_0LB1RA) = lift (Cc (Pos.succ p)).
