(** The chain into this family lands on its anchor up to 0/3
    trailing blanks. *)
Lemma gbo_0RB0RD_0LC1RA_1RB1LC_0LB1RA : forall j, lift (cden [] [] j BB1_0RB0RD_0LC1RA_1RB1LC_0LB1RA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0RD_0LC1RA_1RB1LC_0LB1RA = (StC, (rep [S1;S0] j ++ [S1;S1], S0, ((([S1]) ++ [S0]) ++ [S0]) ++ [S0]))).
  { unfold cden, BB1_0RB0RD_0LC1RA_1RB1LC_0LB1RA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
