Proof. exact lapi_0RB0RD_0LC1RA_1RB1LC_0LB1RA. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0RD_0LC1RA_1RB1LC_0LB1RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0RD_0LC1RA_1RB1LC_0LB1RA p (pow2 j)).
  - exists (4 * j + 17), (cden [] [] j BB1_0RB0RD_0LC1RA_1RB1LC_0LB1RA).
    split; [lia|]. split; [| exact (gbo_0RB0RD_0LC1RA_1RB1LC_0LB1RA j)].
    rewrite (gso_0RB0RD_0LC1RA_1RB1LC_0LB1RA p j E).
    exact (srun_sound tm true true chb_0RB0RD_0LC1RA_1RB1LC_0LB1RA B0_0RB0RD_0LC1RA_1RB1LC_0LB1RA BB1_0RB0RD_0LC1RA_1RB1LC_0LB1RA 4 17
             run_boot_0RB0RD_0LC1RA_1RB1LC_0LB1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 23), (cden [] [] j B1_0RB0RD_0LC1RA_1RB1LC_0LB1RA).
    split; [| exact (geo_0RB0RD_0LC1RA_1RB1LC_0LB1RA p j E)].
    rewrite (gxi_0RB0RD_0LC1RA_1RB1LC_0LB1RA j).
    exact (srun_sound tm true true che_0RB0RD_0LC1RA_1RB1LC_0LB1RA BE0_0RB0RD_0LC1RA_1RB1LC_0LB1RA B1_0RB0RD_0LC1RA_1RB1LC_0LB1RA 4 23
             run_exit_0RB0RD_0LC1RA_1RB1LC_0LB1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0RD_0LC1RA_1RB1LC_0LB1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0RD_0LC1RA_1RB1LC_0LB1RA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0RD_0LC1RA_1RB1LC_0LB1RA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0RD_0LC1RA_1RB1LC_0LB1RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 24.
  assert (H : match csteps tm 24 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 24 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0RD_0LC1RA_1RB1LC_0LB1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0RD_0LC1RA_1RB1LC_0LB1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0RD_0LC1RA_1RB1LC_0LB1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0RD_0LC1RA_1RB1LC_0LB1RA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0RD_0LC1RA_1RB1LC_0LB1RA : forall t, ~ In t pins_0RB0RD_0LC1RA_1RB1LC_0LB1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB0RD_0LC1RA_1RB1LC_0LB1RA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RD_0LC1RA_1RB1LC_0LB1RA [SWin 2; SWinR 4; SCycL 2 0; SWin 6; SCycR 2; SWin 4; SRotL 1; SWin 1; SWin 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RD_0LC1RA_1RB1LC_0LB1RA [SWin 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RD_0LC1RA_1RB1LC_0LB1RA [SWin 2; SWinR 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RD_0LC1RA_1RB1LC_0LB1RA [SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
