(** ** The lap *)

Lemma lap_0RB0RD_0LC1RA_1RD1LC_1LA1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0RD_0LC1RA_1RD1LC_1LA1RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0RD_0LC1RA_1RD1LC_1LA1RB B0_0RB0RD_0LC1RA_1RD1LC_1LA1RB B1_0RB0RD_0LC1RA_1RD1LC_1LA1RB 6 12 p j' [] []).
    + exact run_ovf_0RB0RD_0LC1RA_1RD1LC_1LA1RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0RD_0LC1RA_1RD1LC_1LA1RB p j' E).
    + exact (geo_0RB0RD_0LC1RA_1RD1LC_1LA1RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0RD_0LC1RA_1RD1LC_1LA1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 10.
  assert (H : match csteps tm 10 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 10 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0RD_0LC1RA_1RD1LC_1LA1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0RD_0LC1RA_1RD1LC_1LA1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0RD_0LC1RA_1RD1LC_1LA1RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0RD_0LC1RA_1RD1LC_1LA1RB p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0RD_0LC1RA_1RD1LC_1LA1RB : forall t, ~ In t pins_0RB0RD_0LC1RA_1RD1LC_1LA1RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0RD_0LC1RA_1RD1LC_1LA1RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0RD_0LC1RA_1RD1LC_1LA1RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0RD_0LC1RA_1RD1LC_1LA1RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 1; SWinR 4]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB0RD_0LC1RA_1RD1LC_1LA1RB
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0RD_0LC1RA_1RD1LC_1LA1RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 4]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0RD_0LC1RA_1RD1LC_1LA1RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0RD_0LC1RA_1RD1LC_1LA1RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0RD_0LC1RA_1RD1LC_1LA1RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 1; SWinR 3]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB0RD_0LC1RA_1RD1LC_1LA1RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 3]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_0RB0RD_0LC1RA_1RD1LC_1LA1RB : NeverQuasiHaltsTr tm_0RB0RD_0LC1RA_1RD1LC_1LA1RB.
