    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RD_1LC0LA_0RD0LB_1LB1RD [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0RD_1LC0LA_0RD0LB_1LB1RD [SWinR 2; SRotL 1; SWin 1; SCycL 3 0; SWin 2] (StB, S1) ltac:(vm_compute; reflexivity)
