Lemma lapi_0RB0RD_1RC1RA_1LD1RC_1LA0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
