  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB0RD_1RC1RA_1LD1RC_1LA0LD p q0 E) as (HA & HB).
    exists (0 * 0 + 10). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB0RD_1RC1RA_1LD1RC_1LA0LD Z0_0RB0RD_1RC1RA_1LD1RC_1LA0LD Z1_0RB0RD_1RC1RA_1LD1RC_1LA0LD 0 10
               run_z_0RB0RD_1RC1RA_1LD1RC_1LA0LD (Kp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB0RD_1RC1RA_1LD1RC_1LA0LD p j' q0 E) as (HA & HB).
    exists (2 * j' + 12). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB0RD_1RC1RA_1LD1RC_1LA0LD P0_0RB0RD_1RC1RA_1LD1RC_1LA0LD P1_0RB0RD_1RC1RA_1LD1RC_1LA0LD 2 12
               run_p_0RB0RD_1RC1RA_1LD1RC_1LA0LD (Kp q0 ++ [S0]) [] j'
