(** ** The lap *)

Lemma lap_0RB1LA_0LC1RD_1LA1RA_1RB0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
