  - destruct (lapi_0RB1LA_0LC1RD_1LA1RA_1RB0LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LA_0LC1RD_1LA1RA_1RB0LA B0_0RB1LA_0LC1RD_1LA1RA_1RB0LA B1_0RB1LA_0LC1RD_1LA1RA_1RB0LA 4 10 p j' [] []).
    + exact run_ovf_0RB1LA_0LC1RD_1LA1RA_1RB0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LA_0LC1RD_1LA1RA_1RB0LA p j' E).
    + exact (geo_0RB1LA_0LC1RD_1LA1RA_1RB0LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LA_0LC1RD_1LA1RA_1RB0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
