  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LA_1LA1RC_1RB0LD_0LA1RD B0_0RB1LA_1LA1RC_1RB0LD_0LA1RD B1_0RB1LA_1LA1RC_1RB0LD_0LA1RD 4 6 p j' [] []).
    + exact run_ovf_0RB1LA_1LA1RC_1RB0LD_0LA1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LA_1LA1RC_1RB0LD_0LA1RD p j' E).
    + exact (geo_0RB1LA_1LA1RC_1RB0LD_0LA1RD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LA_1LA1RC_1RB0LD_0LA1RD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
