Lemma fireo_0RB1LA_1LA1RC_1RB0LD_0LA1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LA_1LA1RC_1RB0LD_0LA1RD = Some t ->
