Lemma gsi_0RB1LA_1LA1RC_1RB1RD_1RC0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S1;S0]) [] j A0_0RB1LA_1LA1RC_1RB1RD_1RC0LA.
