  - destruct (lapi_0RB1LA_1LA1RC_1RB1RD_1RC0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LA_1LA1RC_1RB1RD_1RC0LA p j' E).
