(** ** Bootstrap *)

Lemma boot_0RB1LA_1LA1RC_1RB1RD_1RC0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 33.
  assert (H : match csteps tm 33 c0 with
