    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LA_1LA1RC_1RB1RD_1RC0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LA_1LA1RC_1RB1RD_1RC0LA = Some t ->
