Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB1LA_1LA1RC_1RB1RD_1RC0LA t p (pow2 j)).
  - exists (4 * j + 16), (cden [] [] j BB1_0RB1LA_1LA1RC_1RB1RD_1RC0LA). split;
      [| exact (gbo_0RB1LA_1LA1RC_1RB1RD_1RC0LA j)].
