      [exact HB1|].
    exists (6 * j + 4), (cden [] [] j BM1_0RB1LA_1LA1RC_1RD0LA_1LA1RB).
    split; [| exact (gbo2_0RB1LA_1LA1RC_1RD0LA_1LA1RB j)].
    rewrite (gxi_0RB1LA_1LA1RC_1RD0LA_1LA1RB j).
    exact (srun_sound tm true true chm_0RB1LA_1LA1RC_1RD0LA_1LA1RB BM0_0RB1LA_1LA1RC_1RD0LA_1LA1RB BM1_0RB1LA_1LA1RC_1RD0LA_1LA1RB 6 4
             run_shift_0RB1LA_1LA1RC_1RD0LA_1LA1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
