              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LA_1LC1RC_1RD0LA_0LD1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LA_1LC1RC_1RD0LA_0LD1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LA_1LC1RC_1RD0LA_0LD1RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LA_1LC1RC_1RD0LA_0LD1RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_0RB1LA_1LC1RC_1RD0LA_0LD1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1LA_1LC1RC_1RD0LA_0LD1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (6 * j + 8), (cden [] [] j BB1_0RB1LA_1LC1RC_1RD0LA_0LD1RB).
    split; [lia|]. split; [| exact (gbo_0RB1LA_1LC1RC_1RD0LA_0LD1RB j)].
    rewrite (gso_0RB1LA_1LC1RC_1RD0LA_0LD1RB p j E).
    exact (srun_sound tm true true chb_0RB1LA_1LC1RC_1RD0LA_0LD1RB B0_0RB1LA_1LC1RC_1RD0LA_0LD1RB BB1_0RB1LA_1LC1RC_1RD0LA_0LD1RB 6 8
             run_boot_0RB1LA_1LC1RC_1RD0LA_0LD1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_0RB1LA_1LC1RC_1RD0LA_0LD1RB p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (6 * j + 4), (cden [] [] j BM1_0RB1LA_1LC1RC_1RD0LA_0LD1RB).
    split; [| exact (gbo2_0RB1LA_1LC1RC_1RD0LA_0LD1RB j)].
    rewrite (gxi_0RB1LA_1LC1RC_1RD0LA_0LD1RB j).
    exact (srun_sound tm true true chm_0RB1LA_1LC1RC_1RD0LA_0LD1RB BM0_0RB1LA_1LC1RC_1RD0LA_0LD1RB BM1_0RB1LA_1LC1RC_1RD0LA_0LD1RB 6 4
             run_shift_0RB1LA_1LC1RC_1RD0LA_0LD1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB3 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin3 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin2 Cin3 lapin2_0RB1LA_1LC1RC_1RD0LA_0LD1RB p (pow2 j) (pow2 j));
      [exact HB2|].
    exists (6 * j + 8), (cden [] [] j BM31_0RB1LA_1LC1RC_1RD0LA_0LD1RB).
    split; [| exact (gbo3_0RB1LA_1LC1RC_1RD0LA_0LD1RB j)].
    rewrite (gxi2_0RB1LA_1LC1RC_1RD0LA_0LD1RB j).
    exact (srun_sound tm true true chm3_0RB1LA_1LC1RC_1RD0LA_0LD1RB BM30_0RB1LA_1LC1RC_1RD0LA_0LD1RB BM31_0RB1LA_1LC1RC_1RD0LA_0LD1RB 6 8
             run_shift3_0RB1LA_1LC1RC_1RD0LA_0LD1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB3 as (nB & cB & _ & HcB & HlB).
  apply (fire_via_fill tm Cc Cin3 lapin3_0RB1LA_1LC1RC_1RD0LA_0LD1RB t p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (fire_lift_of_csteps tm (fun _ : positive => Cin3 (fill (pow2 j))) xH).
  apply (fire_of_run_instr tm (fun _ : positive => Cin3 (fill (pow2 j)))
                    true true l BE0_0RB1LA_1LC1RC_1RD0LA_0LD1RB xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi3_0RB1LA_1LC1RC_1RD0LA_0LD1RB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LA_1LC1RC_1RD0LA_0LD1RB : forall t, ~ In t pins_0RB1LA_1LC1RC_1RD0LA_0LD1RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB1LA_1LC1RC_1RD0LA_0LD1RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB1LA_1LC1RC_1RD0LA_0LD1RB
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB1LA_1LC1RC_1RD0LA_0LD1RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 5]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB1LA_1LC1RC_1RD0LA_0LD1RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 3]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB1LA_1LC1RC_1RD0LA_0LD1RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB1LA_1LC1RC_1RD0LA_0LD1RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB1LA_1LC1RC_1RD0LA_0LD1RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 4]).
    vm_compute; reflexivity.
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1LA_1LC1RC_1RD0LA_0LD1RB (StD, S0)).
    intros p1 j1 E1.
    exact (firex_0RB1LA_1LC1RC_1RD0LA_0LD1RB [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 2] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB1LA_1LC1RC_1RD0LA_0LD1RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_0RB1LA_1LC1RC_1RD0LA_0LD1RB : NeverQuasiHaltsTr tmm_0RB1LA_1LC1RC_1RD0LA_0LD1RB.
Proof.
  apply (glue_neverqhtr tmm_0RB1LA_1LC1RC_1RD0LA_0LD1RB pins_0RB1LA_1LC1RC_1RD0LA_0LD1RB Cc 1).
